// Date and challenge number are anchored to America/New_York, not the visitor's timezone.
function easternDayKey(date=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(date);const v=Object.fromEntries(parts.map(p=>[p.type,p.value]));return `${v.year}-${v.month}-${v.day}`}
const DAY_KEY=easternDayKey();
const DAY_NUMBER=Math.floor((Date.parse(DAY_KEY+'T00:00:00Z')-Date.parse('2026-10-13T00:00:00Z'))/86400000)+1;
function seededRandom(seed){return function(){seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return ((t^t>>>14)>>>0)/4294967296}}
