function expandAcceptedAnswers(aliases){
 const out=new Set(aliases.map(norm));
 for(const group of SCHOOL_EQUIVALENTS){if(group.some(name=>out.has(norm(name))))group.forEach(name=>out.add(norm(name)));}
 const primary=norm(aliases[0]||'');
 const full=(aliases[0]||'').trim();
 // A surname is accepted even when other players share it; no common first-name guessing.
 if(full.includes(' ') && !/\d/.test(full) && !TEAM_EQUIVALENTS.some(g=>g.some(t=>norm(t)===primary))){
   const tokens=full.split(/\s+/);const suffixes=new Set(['jr','jr.','sr','sr.','ii','iii','iv']);
   while(tokens.length>1&&suffixes.has(tokens[tokens.length-1].toLowerCase()))tokens.pop();
   if(tokens.length>1){
     const last=tokens[tokens.length-1];if(last.length>=3)out.add(norm(last));
     const first=norm(tokens[0]);if(STANDALONE_FIRST_NAMES.has(first))out.add(first);
   }
 }
 for(const group of TEAM_EQUIVALENTS){if(group.some(name=>norm(name)===primary))group.forEach(name=>out.add(norm(name)));}
 for(const [key,nicks] of Object.entries(PLAYER_NICKNAMES)){if(norm(key).replace(/ /g,'')===primary.replace(/ /g,''))nicks.forEach(nick=>out.add(norm(nick)));}
 return [...out];
}
function isCorrect(input,aliases){
 const n=norm(input);if(!n)return false;
 return expandAcceptedAnswers(aliases).some(a=>{
  if(n===a)return true;
  if(n.length<5||a.length<5||/\d/.test(n)||/\d/.test(a))return false;
  // Do not fuzzy-match short/common names into unrelated answers.
  const allowance=Math.max(n.length,a.length)>=9?2:1;
  return Math.abs(n.length-a.length)<=allowance&&distance(n,a)<=allowance;
 });
}
