const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let audioContext=null;
function countdownSound(kind){
  try {
    const AC=window.AudioContext||window.webkitAudioContext;
    if(!AC)return;
    audioContext=audioContext||new AC();
    if(audioContext.state==='suspended')audioContext.resume();
    const start=audioContext.currentTime;
    // Crisp, short warning beeps at 5, 4, 3, 2, 1.
    // At zero, a distinct low double-tone buzzer sounds instead.
    const tones=kind==='buzzer'?[{freq:175,delay:0,duration:.42},{freq:130,delay:.05,duration:.43}]:[{freq:880,delay:0,duration:.105}];
    for(const tone of tones){
      const osc=audioContext.createOscillator();
      const gain=audioContext.createGain();
      const at=start+tone.delay;
      osc.type=kind==='buzzer'?'sawtooth':'sine';
      osc.frequency.setValueAtTime(tone.freq,at);
      gain.gain.setValueAtTime(.0001,at);
      gain.gain.exponentialRampToValueAtTime(kind==='buzzer'?.095:.075,at+.012);
      gain.gain.setValueAtTime(kind==='buzzer'?.095:.075,at+Math.max(.014,tone.duration-.055));
      gain.gain.exponentialRampToValueAtTime(.0001,at+tone.duration);
      osc.connect(gain).connect(audioContext.destination);
      osc.start(at);osc.stop(at+tone.duration+.02);
    }
  }catch(e){}
}
function sound(kind='click'){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;audioContext=audioContext||new AC();if(audioContext.state==='suspended')audioContext.resume();const notes=kind==='correct'?[[523,.00,.10],[659,.11,.10],[784,.22,.16]]:kind==='wrong'?[[260,0,.13],[190,.14,.17]]:kind==='finish'?[[440,0,.09],[554,.11,.09],[659,.22,.09],[880,.34,.23]]:[[440,0,.045]];for(const [freq,offset,duration] of notes){const osc=audioContext.createOscillator(),gain=audioContext.createGain(),at=audioContext.currentTime+offset;osc.type=kind==='wrong'?'triangle':'sine';osc.frequency.setValueAtTime(freq,at);gain.gain.setValueAtTime(.0001,at);gain.gain.exponentialRampToValueAtTime(kind==='click'?.055:.11,at+.012);gain.gain.exponentialRampToValueAtTime(.0001,at+duration);osc.connect(gain).connect(audioContext.destination);osc.start(at);osc.stop(at+duration+.02)}}catch(e){}}
