async function shareResults(){sound('click');const txt=shareText();if(navigator.share){try{await navigator.share({title:'Ball360 — Daily Challenge',text:txt});return}catch(e){if(e.name==='AbortError')return}}try{await navigator.clipboard.writeText(txt);showShareStatus('Copied! Paste it into a text or group chat.')}catch(e){const ta=document.createElement('textarea');ta.value=txt;ta.style.cssText='position:fixed;left:-9999px';document.body.appendChild(ta);ta.select();try{document.execCommand('copy');showShareStatus('Copied! Paste it into a text or group chat.')}catch(err){showShareStatus('Select and copy the results below.')}ta.remove()}}
