const config = window.BALL360_CONFIG || {};
let sbClient = null;
let globalStats=null, globalStatus=sbClient&&config.sharedScores?'loading':'error', globalSubmitPending=false;
let perfect360Count=null,perfect360Status=sbClient?'loading':'error';
async function fetchPerfect360(){
 if(!sbClient)return;
 try{const r=await sbClient.rpc('get_perfect_360_count',{p_day:DAY_KEY});
 if(r.error)throw r.error;perfect360Count=Number(r.data);if(!Number.isFinite(perfect360Count))throw Error('Invalid perfect-score count');perfect360Status='ready';
 }catch(e){perfect360Status='error';console.warn('Perfect 360 count unavailable:',e.message)}
}
function perfect360HTML(){return '<div class="perfect-club"><div class="eyebrow">♛ PERFECT 360 CLUB</div>'+(perfect360Status==='ready'?'<strong>'+perfect360Count+'</strong><p class="note">player'+(perfect360Count===1?'':'s')+' scored a perfect 360/360 today</p>':'<p class="note">'+(perfect360Status==='error'?'Perfect-score count unavailable right now.':'Checking today’s perfect scores…')+'</p>')+'</div>'}

async function ensureAnonymousUser(){
 if(!sbClient)throw Error('Supabase client unavailable. Check your internet connection.');
 let {data:{session},error}=await sbClient.auth.getSession();if(error)throw error;
 if(!session){const r=await sbClient.auth.signInAnonymously();if(r.error)throw r.error;session=r.data.session;}
 if(!session?.user?.id)throw Error('Anonymous sign-in did not succeed.');
 return session.user.id;
}
async function getSharedStats(resultScore=score){
 if(!sbClient||!config.sharedScores)return;
 try{await ensureAnonymousUser();const r=await sbClient.rpc('ball360_daily_stats',{p_day:DAY_KEY,p_score:resultScore});if(r.error)throw r.error;
 globalStats=r.data;globalStatus='ready';
 }catch(e){globalStatus='error';console.warn('Shared score stats unavailable:',e.message)}
 await fetchPerfect360();
 if(mode==='daily'&&stage==='finished')render();
}
async function publishScore(){
 if(globalSubmitPending||!sbClient||!config.sharedScores)return;
 const finishedScore=score;
 globalSubmitPending=true;globalStatus='loading';
 try{const uid=await ensureAnonymousUser();
 const r=await sbClient.from('ball360_daily_scores').insert({user_id:uid,challenge_day:DAY_KEY,score:finishedScore});
 // Unique user/day protects against duplicate submissions. Existing scores are immutable.
 if(r.error&&r.error.code!=='23505')throw r.error;
 await getSharedStats(finishedScore);
 }catch(e){globalStatus='error';console.warn('Score not published:',e.message);if(mode==='daily'&&stage==='finished')render();}
 finally{globalSubmitPending=false;}
}
