function savedCompletions(){return readLocal('ball360_completed_days',{});}
function playerStats(){
 const completed=savedCompletions(),days=Object.keys(completed).sort(),scores=days.map(k=>Number(completed[k].score)||0);
 const best=scores.length?Math.max(...scores):null,avg=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):null;
 // Current streak includes today if played, otherwise runs through yesterday.
 const oneDayBack=key=>{const dt=new Date(key+'T12:00:00Z');dt.setUTCDate(dt.getUTCDate()-1);return dt.toISOString().slice(0,10)};
 let cursor=completed[DAY_KEY]?DAY_KEY:oneDayBack(DAY_KEY),streak=0;
 while(completed[cursor]){streak++;cursor=oneDayBack(cursor)}
 return {played:days.length,best,avg,streak};
}
function statsHTML(){const st=playerStats();return '<div class="player-stats"><div><strong>🔥 '+st.streak+'</strong><small>DAY STREAK</small></div><div><strong>'+(st.best===null?'—':st.best)+'</strong><small>PERSONAL BEST</small></div><div><strong>'+(st.avg===null?'—':st.avg)+'</strong><small>AVG SCORE</small></div><div><strong>'+st.played+'</strong><small>DAYS PLAYED</small></div></div>'}
function refreshRecords(){
 const panel=document.getElementById('recordsContent');
 if(panel)panel.innerHTML='<div class="eyebrow" style="margin-bottom:10px">YOUR BALL360 RECORDS</div>'+statsHTML()+'<p class="note" style="margin-bottom:0">Stats are saved on this browser during testing.</p>';
}
function toggleRecords(){
 const panel=document.getElementById('recordsContent'),button=document.getElementById('recordsToggle');
 if(!panel||!button)return;
 const open=panel.hidden;
 panel.hidden=!open;
 button.setAttribute('aria-expanded',String(open));
 button.innerHTML=open?'🔥 HIDE MY STATS <span class="records-arrow">⌄</span>':'🔥 VIEW MY STATS <span class="records-arrow">⌄</span>';
 if(open)refreshRecords();
}
function tierInfo(v){return v===360?{name:'THE GOAT!!!!!',cls:'tier-goat',icon:'♛'}:v>=330?{name:'BALL360 LEGEND',cls:'tier-legend',icon:'★'}:v>=280?{name:'MVP Candidate',cls:'tier-mvp',icon:'★'}:v>=220?{name:'All-Star',cls:'tier-allstar',icon:'★'}:v>=160?{name:'Solid Starter',cls:'tier-starter',icon:'★'}:v>=80?{name:'Bench Player',cls:'tier-bench',icon:'★'}:{name:'Casual Fan',cls:'tier-fan',icon:'★'}}
function scoreTitle(v){return tierInfo(v).name}
function tierHTML(v){const t=tierInfo(v);return '<span class="score-title '+t.cls+'"><span class="tier-icon" aria-hidden="true">'+t.icon+'</span>'+t.name+'</span>'}
function challengeDisplayDate(){const [y,m,d]=DAY_KEY.split('-');return Number(m)+'/'+Number(d)+'/'+y}
let refreshBusy=false,refreshMessage='';
async function refreshGlobalResults(){if(refreshBusy)return;refreshBusy=true;refreshMessage='';updateRefreshUI();try{await getSharedStats();refreshMessage=globalStatus==='ready'?'Updated just now ✓':'Could not refresh. Try again.';}catch(e){refreshMessage='Could not refresh. Try again.';}finally{refreshBusy=false;updateRefreshUI()}}
function updateRefreshUI(){const btn=document.getElementById('globalRefreshButton');if(btn){btn.disabled=refreshBusy;btn.innerHTML=refreshBusy?'<span class="refresh-spinner" aria-hidden="true"></span>Refreshing results...':'↻ Refresh results';}const status=document.getElementById('globalRefreshStatus');if(status)status.textContent=refreshMessage}
function refreshControl(){return '<button type="button" id="globalRefreshButton" class="refresh-results" onclick="refreshGlobalResults()" '+(refreshBusy?'disabled':'')+'>'+(refreshBusy?'<span class="refresh-spinner" aria-hidden="true"></span>Refreshing results...':'↻ Refresh results')+'</button><span id="globalRefreshStatus" class="refresh-status" role="status" aria-live="polite">'+refreshMessage+'</span>'}

function saveScore(){
 const completed=savedCompletions();
 if(completed[DAY_KEY])return; // Prevent double counting refreshes.
 completed[DAY_KEY]={score,correct:history.filter(h=>h.correct).length};
 localStorage.setItem('ball360_completed_days',JSON.stringify(completed));refreshRecords();
 const arr=todaysScores();arr.push({score,at:Date.now()});localStorage.setItem(localScoreKey,JSON.stringify(arr));updateBoard();
}
function updateBoard(){}
function resultsExtras(){
 const heading='<div class="eyebrow compare-date">HOW YOU COMPARE - '+challengeDisplayDate()+'</div>';
 const data=globalStats;
 if(!data){return '<div class="result">'+heading+'<p class="note">'+(globalStatus==='error'?'Shared results unavailable right now. Your personal score is saved on this device. Check Supabase setup or try refreshing.':'Loading shared results from all Ball360 players…')+'</p>'+refreshControl()+perfect360HTML()+'</div>';}
 const n=Number(data.players)||0,mean=Number(data.average)||0,sd=Number(data.stddev)||0,below=Number(data.below)||0;
 const pct=n?Math.round(100*below/n):0;
 const pctClass=pct>50?'above':pct<50?'below':'even';
 const bands=[[0,59],[60,119],[120,179],[180,239],[240,299],[300,360]];
 const counts=Array.isArray(data.bands)?data.bands.map(Number):[0,0,0,0,0,0];
 const max=Math.max(1,...counts);
 const detail=n<10?'Only '+n+' player'+(n===1?'':'s')+' so far — the distribution will become more useful with more players.':sd?'Your score is '+Math.abs((score-mean)/sd).toFixed(2)+' standard deviations '+(score>=mean?'above':'below')+' the average.':'Everyone has the same score so far.';
 return '<div class="result">'+heading+'<div class="mini-grid"><div><strong>'+n+'</strong><small>PLAYERS TODAY</small></div><div><strong>'+Math.round(mean)+'</strong><small>DAILY AVERAGE</small></div><div><strong class="compare-percent '+pctClass+'">'+pct+'%</strong><small>YOU BEAT</small></div></div><p class="note">'+detail+'</p><h3 style="font-size:16px">SCORE DISTRIBUTION</h3>'+bands.map(([a,b],i)=>'<div class="barrow"><span class="barlabel">'+a+'–'+b+(score>=a&&score<=b?' <span class="youmarker">●</span>':'')+'</span><div class="bartrack"><div class="barfill" style="width:'+100*counts[i]/max+'%"></div></div><span class="barvalue">'+counts[i]+'</span></div>').join('')+'<p class="note">Shared results from completed games submitted to Ball360 today.</p><p class="note">'+refreshControl()+' · Standard deviation: '+sd.toFixed(1)+' points</p>'+perfect360HTML()+'</div>';
}
const attemptKey='ball360_attempt_'+DAY_KEY;
const practiceKey='ball360_unlimited_attempt';
let mode = 'daily';

function activeAttemptKey() {
  return mode === 'daily' ? attemptKey : practiceKey;
}

function practiceQuestions() {
  const seed = (Math.random() * 0x100000000) >>> 0;
  const template = BALANCED_DAILY_IDS[seed % BALANCED_DAILY_IDS.length].map(id => QUESTION_BY_ID[id]);
  const sportByCategory = new Map(template.map(item => [item.cat, item.sport]));
  const excluded = new Set([...dailyQuestions(), ...(readLocal(practiceKey, {})?.questions || [])].map(item => item.id));
  return shuffleWithSeed(CATEGORY_BANK.filter(category => sportByCategory.has(category.cat)), seed).map((category, index) => {
    const pool = category.items.filter(item => item.sport === sportByCategory.get(category.cat) && !excluded.has(item.id));
    const candidates = pool.length ? pool : category.items.filter(item => item.sport === sportByCategory.get(category.cat));
    return {...shuffleWithSeed(candidates, seed + index + 1)[0], cat:category.cat};
  });
}
let countdownInterval=null,questionDeadline=0;
function saveAttempt(){
 if(stage==='admin'||stage==='home')return;
 localStorage.setItem(activeAttemptKey(),JSON.stringify({day:DAY_KEY,round,score,used,stage,seconds,wager,history,questionDeadline,questions,answerDraft}));
}
function loadAttempt(){
 const a=readLocal(activeAttemptKey(),null);
 if(!a||(mode==='daily'&&a.day!==DAY_KEY)||!Array.isArray(a.history)||!Array.isArray(a.used)||!Array.isArray(a.questions)||a.questions.length!==8)return;
 round=Math.max(0,Math.min(8,Number(a.round)||0));score=Number(a.score)||0;used=a.used;stage=['category','question','result','finished'].includes(a.stage)?a.stage:'home';seconds=Number(a.seconds)||30;wager=Number(a.wager)||0;history=a.history;questionDeadline=Number(a.questionDeadline)||0;questions=a.questions;
 answerDraft=typeof a.answerDraft==='string'?a.answerDraft:'';
 if(stage==='question')seconds=Math.max(0,Math.ceil((questionDeadline-Date.now())/1000));
 return true;
}
function timeUntilNextET(){
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/New_York',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date());
 const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return 86400-(Number(p.hour)*3600+Number(p.minute)*60+Number(p.second));
}
function countdownHTML(){return '<div class="next-challenge"><div class="eyebrow">NEXT DAILY CHALLENGE IN</div><div class="countdown-grid"><div class="countdown-unit"><strong id="cdHours">--</strong><small>HOURS</small></div><div class="countdown-unit"><strong id="cdMinutes">--</strong><small>MINUTES</small></div><div class="countdown-unit"><strong id="cdSeconds">--</strong><small>SECONDS</small></div></div><p class="note">New questions unlock at midnight Eastern Time.</p></div>'}
function tickCountdown(){
 if(easternDayKey()!==DAY_KEY){location.reload();return}
 const t=timeUntilNextET();const pad=x=>String(x).padStart(2,'0');
 const h=document.getElementById('cdHours'),m=document.getElementById('cdMinutes'),sec=document.getElementById('cdSeconds');
 if(h)h.textContent=pad(Math.floor(t/3600));if(m)m.textContent=pad(Math.floor(t%3600/60));if(sec)sec.textContent=pad(t%60);
}
function startCountdown(){clearInterval(countdownInterval);tickCountdown();countdownInterval=setInterval(tickCountdown,1000)}
function resumeAttempt(){sound('click');const a=readLocal(attemptKey,null);if(!a)return;loadAttempt();render()}
const WAGERS = [10, 20, 30, 40, 50, 60, 70, 80];
function progress() {
  return '<div class="progress" aria-hidden="true">' + questions.map((_, i) =>
    '<i class="' + (i < history.length ? 'done' : '') + '"></i>').join('') + '</div>';
}

function render() {
  clearInterval(clock);
  clearInterval(countdownInterval);
  document.body.classList.toggle('finished-screen', stage === 'finished');
  document.body.classList.toggle('home-screen', stage === 'home');
  if (stage === 'home') {
    const daily = readLocal(attemptKey, null);
    const practice = readLocal(practiceKey, null);
    const dailyLabel = daily?.stage === 'finished' ? 'View today’s results' : daily ? 'Resume Daily Challenge' : 'Play Daily Challenge';
    const practiceLabel = practice && practice.stage !== 'finished' ? 'Resume Unlimited' : 'Play Unlimited';
    el.innerHTML = '<div class="mode-actions"><button class="button" onclick="start()">'
      + dailyLabel + ' <span aria-hidden="true">→</span></button>'
      + '<button class="button mode-secondary" onclick="start(&quot;unlimited&quot;)">'
      + practiceLabel + ' <span aria-hidden="true">→</span></button></div>';
    return;
  }
  if(stage==='finished'){
  const review=history.map((h,i)=>({...h,question:questions[i],originalRound:i+1})).sort((a,b)=>a.wager-b.wager).map((h,i)=>'<details class="answer-review"><summary><span class="review-icon '+(h.correct?'good':'bad')+'">'+(h.correct?'✓':'✕')+'</span><span class="review-main"><strong>'+escapeHTML(h.question.cat)+'</strong><small>Round '+h.originalRound+' · '+h.wager+' point wager</small></span><span class="review-points '+(h.correct?'good':'bad')+'">'+(h.correct?'+':'')+h.earned+' / '+h.wager+' pts</span><span class="review-chevron">⌄</span></summary><div class="review-detail"><span class="review-answer-label">Your answer:</span> <span class="'+(h.correct?'good':'bad')+'">'+escapeHTML(h.answer||'(No answer — time expired)')+'</span><br><span class="review-answer-label">Correct answer:</span> <strong>'+escapeHTML(h.question.a[0])+'</strong></div></details>').join('');
  if (mode === 'unlimited') {
    el.innerHTML = '<div class="final-grid"><section class="final-card"><div class="eyebrow">UNLIMITED</div><h2>Your final score</h2>'
      + tierHTML(score) + '<div class="score">' + score + ' <span style="font-size:20px;color:#aaa">/ 360</span></div>'
      + '<p>' + history.filter(item => item.correct).length + ' of 8 correct</p>'
      + '<button class="button" onclick="start(&quot;unlimited&quot;,true)">Play again →</button>'
      + '<button class="nav-button" onclick="goHome()">Back to modes</button></section>'
      + '<section class="final-card"><h2>Your answers</h2>' + review + '</section></div>';
    return;
  }
  el.innerHTML='<div class="final-grid"><div class="final-column"><section class="final-card"><div class="eyebrow">CHALLENGE COMPLETE</div><h2 style="margin:10px 0">Your final score</h2>'+tierHTML(score)+'<div class="score">'+score+' <span style="font-size:20px;color:#aaa">/ 360</span></div><div class="result">'+history.filter(x=>x.correct).length+' of 8 correct · '+Math.round(score/360*100)+'% of possible points</div>'+statsHTML()+'</section><section class="final-card"><div class="eyebrow">YOUR ANSWERS</div><p class="note">Tap any round to see what you typed and the correct answer.</p>'+review+'</section></div><div class="final-column"><section class="final-card"><div class="eyebrow">SHARE YOUR SCORE</div><p class="note">No question spoilers. Boxes are shown from 10 to 80 points.</p><div class="share-preview">'+escapeHTML(shareText())+'</div><button class="button" onclick="shareResults()">↗ SHARE RESULTS</button><p class="note" id="sharestatus" aria-live="polite"></p></section><section class="final-card">'+resultsExtras()+'</section></div></div><div class="final-bottom"><div class="note">You have completed today’s challenge. Come back tomorrow for eight new questions!</div>' + countdownHTML() + '</div>';startCountdown();return}  const item = questions[round];
  const meta = '<div class="round-meta"><span>' + (mode === 'unlimited' ? 'Unlimited · Round ' : 'Round ') + (round + 1) + '/8</span><span>' + score + '/360 pts</span></div>';
  const category = '<p class="eyebrow">' + escapeHTML(item.sport) + ' / ' + escapeHTML(item.cat) + '</p>';
  if (stage === 'category') {
    el.innerHTML = meta + progress() + category + '<h2>Choose your wager</h2>' +
      '<div class="wagers">' + WAGERS.map(value =>
        '<button type="button" class="wager" aria-label="' + value + ' points" ' +
        (used.includes(value) ? 'disabled' : '') + ' onclick="choose(' + value + ')"><strong>' +
        value + '</strong></button>').join('') + '</div>';
    el.querySelector('.wager:not(:disabled)')?.focus({preventScroll:true});
    return;
  }
  if (stage === 'question') {
    el.innerHTML = meta + progress() + category +
      '<div class="question-meta"><span>' + wager + ' pts at stake</span><span class="timer" id="timer">0:30</span></div>' +
      '<h2 class="question">' + escapeHTML(item.q) + '</h2><form id="answerform">' +
      '<label class="visually-hidden" for="answer">Your answer</label><input id="answer" placeholder="Your answer" autocomplete="off" maxlength="100" required>' +
      '<button class="button">Submit answer</button></form>';
    const input = document.getElementById('answer');
    input.value = answerDraft;
    input.addEventListener('input', () => {answerDraft = input.value; saveAttempt();});
    document.getElementById('answerform').onsubmit = handleAnswerSubmit;
    input.focus({preventScroll:true});
    clock = setInterval(tickQuestion, 200);
    tickQuestion();
    return;
  }
  const result = history[round];
  el.innerHTML = meta + progress() +
    '<div class="category ' + (result.correct ? 'feedback-good' : 'feedback-bad') + '">' +
    '<h2>' + (result.correct ? 'Correct' : 'Not quite') + '</h2><div class="score">+' + result.earned +
    '</div><p class="muted">Your answer: ' + escapeHTML(result.answer || 'Time expired') +
    '<br>Correct answer: <strong>' + escapeHTML(item.a[0]) + '</strong></p></div>' +
    '<button class="button" onclick="next()">' + (round === 7 ? 'View final score' : 'Next category') + ' →</button>';
  el.querySelector('button').focus({preventScroll:true});
}

let answerDraft = '';
let lastBeep;
function tickQuestion() {
  seconds = Math.max(0, Math.ceil((questionDeadline - Date.now()) / 1000));
  const timer = document.getElementById('timer');
  timer.textContent = '0:' + String(seconds).padStart(2, '0');
  timer.classList.toggle('urgent', seconds <= 5);
  if (!seconds) {
    countdownSound('buzzer');
    submit(true);
  } else if (seconds <= 5 && seconds !== lastBeep) {
    lastBeep = seconds;
    countdownSound('tick');
  }
}
let dailySet = dailyQuestions();
function resetRoundState() {
  round = 0;
  score = 0;
  used = [];
  history = [];
  answerDraft = '';
  wager = 0;
  questionDeadline = 0;
}
function goHome() {
  resetRoundState();
  stage = 'home';
  render();
}
function start(playMode = 'daily', replay = false) {
  if (stage !== 'home' && !(replay && mode === 'unlimited' && stage === 'finished')) return;
  mode = playMode;
  if (mode === 'daily' && easternDayKey() !== DAY_KEY) { location.reload(); return; }
  if (!replay && loadAttempt() && (mode === 'daily' || stage !== 'finished')) {
    render();
    if (mode === 'daily' && stage === 'finished') { saveScore(); publishScore(); }
    return;
  }
  resetRoundState();
  questions = mode === 'daily' ? dailySet : practiceQuestions();
  sound('click');
  stage = 'category';
  saveAttempt();
  render();
}
function choose(value) {
  if (stage !== 'category' || !WAGERS.includes(value) || used.includes(value)) return;
  sound('click');
  wager = value;
  used.push(value);
  answerDraft = '';
  lastBeep = null;
  questionDeadline = Date.now() + 30000;
  stage = 'question';
  saveAttempt();
  render();
}
function submit(timedOut) {
  if (stage !== 'question') return;
  const answer = answerDraft.trim();
  if (!answer && !timedOut) return;
  clearInterval(clock);
  const correct = isCorrect(answer, questions[round].a);
  const earned = correct ? wager : 0;
  score += earned;
  history[round] = {correct, earned, answer, wager};
  sound(correct ? 'correct' : 'wrong');
  stage = 'result';
  saveAttempt();
  render();
}
function next() {
  if (stage !== 'result') return;
  sound(round === 7 ? 'finish' : 'click');
  round++;
  stage = round >= questions.length ? 'finished' : 'category';
  saveAttempt();
  if (mode === 'daily' && stage === 'finished') {
    saveScore();
    publishScore();
    updateTrophyNav();
  }
  render();
}
// Desktop keyboard shortcut: Enter advances from round feedback to the next category or final score.
// Do not intercept Enter while typing, using a button, or editing questions.
document.addEventListener('keydown', function(event) {
  if (event.key !== 'Enter' || event.repeat || event.isComposing || stage !== 'result') return;
  const target = event.target;
  if (target && (target.closest('input, textarea, select, button, a, [contenteditable="true"]'))) return;
  event.preventDefault();
  next();
});
async function initializeGame() {
  if (config.sharedScores || config.sharedQuestions) {
    try {
      sbClient = await Promise.race([connectSupabase(), new Promise(resolve => setTimeout(() => resolve(null), 3500))]);
    } catch (error) { console.warn('Shared features unavailable:', error); }
    if (sbClient && config.sharedScores) globalStatus = perfect360Status = 'loading';
  }
  if (sbClient && config.sharedQuestions) {
    try {
      const {data, error} = await sbClient.from('ball360_question_schedules').select('questions')
        .eq('day', DAY_KEY).abortSignal(AbortSignal.timeout(3500)).maybeSingle();
      if (!error && validQuestions(data?.questions)) dailySet = data.questions;
    } catch (error) { console.warn('Using the built-in challenge:', error.message); }
  }
  if (!config.sharedQuestions) {
    const local = readLocal('ball360_questions_' + DAY_KEY, null);
    if (validQuestions(local)) dailySet = local;
  }
  document.getElementById('daylabel').textContent = '#' + DAY_NUMBER;
  refreshRecords();
  updateTrophyNav();
  el.removeAttribute('aria-busy');
  render();
}
function validQuestions(rows) {
  return Array.isArray(rows) && rows.length === 8 && new Set(rows.map(row => row?.cat)).size === 8 &&
    rows.every(row => row && CATEGORY_BANK.some(category => category.cat === row.cat) &&
      ['NBA', 'NFL'].includes(row.sport) && typeof row.q === 'string' && row.q.trim() &&
      Array.isArray(row.a) && row.a.length && row.a.every(answer => typeof answer === 'string' && norm(answer)));
}

